import React from 'react';

export default function Testimonials({ darkMode }) {
  const reviews = [
    { name: 'أحمد محمد', text: 'تجربة رائعة! وجدت منزلي المثالي في أسبوع واحد بفضل هذا الموقع.', role: 'عميل سعيد', img: 'https://randomuser.me/api/portraits/men/32.jpg' },
    { name: 'سارة علي', text: 'خدمة احترافية ودعم فني ممتاز طوال الوقت. أنصح به بشدة.', role: 'مستثمرة', img: 'https://randomuser.me/api/portraits/women/44.jpg' },
    { name: 'محمود حسن', text: 'أفضل موقع عقارات تعاملت معه، سهولة في البحث وتنوع في الخيارات.', role: 'مشتري لأول مرة', img: 'https://randomuser.me/api/portraits/men/85.jpg' },
  ];

  return (
    <div className={`py-5 ${darkMode ? 'bg-dark' : 'bg-white'}`}>
      <div className="container">
        <div className="text-center mb-5">
          <h2 className={`fw-bold ${darkMode ? 'text-white' : ''}`}>💬 قصص نجاح عملائنا</h2>
          <p className={darkMode ? 'text-white-50' : 'text-muted'}>نفتخر بخدمة الآلاف من العملاء السعداء</p>
        </div>
        <div className="row g-4">
          {reviews.map((review, idx) => (
            <div key={idx} className="col-md-4">
              <div className={`card h-100 border-0 shadow-sm text-center p-4 ${darkMode ? 'bg-secondary text-white' : ''}`} style={{borderRadius: '15px'}}>
                <div className="mb-3">
                  <img src={review.img} alt={review.name} className="rounded-circle shadow-sm" style={{width: 80, height: 80, objectFit: 'cover'}} />
                </div>
                <h5 className="card-title">{review.name}</h5>
                <h6 className={`card-subtitle mb-3 small ${darkMode ? 'text-light' : 'text-primary'}`}>{review.role}</h6>
                <p className={`card-text fst-italic ${darkMode ? 'text-white-50' : 'text-muted'}`}>"{review.text}"</p>
                <div className="text-warning">⭐⭐⭐⭐⭐</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
